#!/usr/bin/env python3
"""
01_train_GeneCompass.py - prepare inputs and train GeneCompass for NOCAP benchmarking

This release-facing entry point integrates GeneCompass preprocessing, coexpression
network precomputation, and multi-seed training into one train-stage script.

Usage:
    python 01_train_GeneCompass.py --seeds 1 2 3 4 5 --epochs 15
    python 01_train_GeneCompass.py --skip_preprocess --skip_coexpression --seeds 1 2 3 4 5
"""

import argparse
import runpy
import shlex
import sys

STAGE_SOURCES = {'preprocess': '#!/usr/bin/env python3\n"""\nIntegrated Preprocessing Pipeline for GeneCompass + GEARS Training\n\nThis script performs all preprocessing steps required for GeneCompass + GEARS training\non the NOCAP 512k dataset. It replicates the exact preprocessing used for the\nbenchmark training runs (GPU 0 seeds 1-5, GPU 1 seeds 6-10).\n\nPipeline Steps:\n1. Load raw h5ad data and add GEARS-required columns\n2. Compute DE genes using pseudobulk fold-change method\n3. Compute non-zero/non-dropout gene indices\n4. Generate prior knowledge embeddings (64-dim PCA from 4 sources)\n5. Create PyG cell graphs for training\n\nUsage:\n    python 01_train_GeneCompass.py [preprocess stage] --step all          # Run all steps\n    python 01_train_GeneCompass.py [preprocess stage] --step data         # Step 1-3: Data preparation\n    python 01_train_GeneCompass.py [preprocess stage] --step embeddings   # Step 4: Prior knowledge embeddings\n    python 01_train_GeneCompass.py [preprocess stage] --step pyg          # Step 5: PyG cell graphs\n"""\n\nimport os\nimport sys\nimport argparse\nimport pickle\nimport shutil\nimport numpy as np\nimport pandas as pd\nimport scanpy as sc\nfrom scipy.sparse import csr_matrix, issparse\nfrom sklearn.decomposition import PCA\nimport multiprocessing as mp\nfrom functools import partial\nimport psutil\nimport time\nimport torch\nfrom torch_geometric.data import Data\n\n# Configuration\nDATA_DIR = "<DATA_ROOT>/05.Behchmarking_DL/data/NOCAP_Telen_512k_normalized"\nRAW_H5AD = "<DATA_ROOT>/05.Behchmarking_DL/data/NOCAP_Telen_512k.h5ad"\nNORMALIZED_H5AD = os.path.join(DATA_DIR, "NOCAP_Telen_512k_normalized", "perturb_processed.h5ad")\nEMBEDDINGS_DIR = "<DATA_ROOT>/05.Behchmarking_DL/GeneCompass/embeddings"\nOLD_DATA_DIR = "<DATA_ROOT>/05.Behchmarking_DL/data/NOCAP_Telen_normalized"\n\n# Prior knowledge files (from original 80k dataset, scaled to 512k genes)\nPRIOR_KNOWLEDGE_DIR = "<DATA_ROOT>/05.Behchmarking_DL/data/NOCAP_Telen_normalized/NOCAP_Telen_normalized"\nGO_FILE = os.path.join(PRIOR_KNOWLEDGE_DIR, "go.csv")\nGO_ALL_FILE = os.path.join(PRIOR_KNOWLEDGE_DIR, "go_all.pkl")\n\n\ndef print_step(step_num, msg):\n    """Print step with formatting."""\n    print(f"\\n{\'=\'*60}")\n    print(f"Step {step_num}: {msg}")\n    print(f"{\'=\'*60}")\n\n\n# =============================================================================\n# STEP 1-3: Data preparation\n# =============================================================================\n\ndef prepare_gears_data(raw_h5ad_path, output_dir):\n    """\n    Load raw h5ad data and prepare it for GEARS training.\n    Adds required columns and computes DE genes.\n    """\n    print_step("1-3", "Preparing GEARS data format")\n\n    # Create output directory\n    inner_dir = os.path.join(output_dir, os.path.basename(output_dir))\n    os.makedirs(inner_dir, exist_ok=True)\n    output_h5ad = os.path.join(inner_dir, "perturb_processed.h5ad")\n\n    # Load raw data\n    print(f"Loading raw data from: {raw_h5ad_path}")\n    adata = sc.read_h5ad(raw_h5ad_path)\n    print(f"Loaded: {adata.shape}")\n\n    # Ensure \'condition\' column exists (perturbation info)\n    if \'condition\' not in adata.obs.columns and \'perturbation\' in adata.obs.columns:\n        adata.obs[\'condition\'] = adata.obs[\'perturbation\']\n\n    # Reformat condition names: "ctrl+GENE" -> "GENE+ctrl" for GEARS compatibility\n    print("Reformatting condition names...")\n    original_conditions = adata.obs[\'condition\'].unique()\n    print(f"Original conditions: {len(original_conditions)}")\n\n    def reformat_condition(cond):\n        if \'+\' in cond:\n            parts = cond.split(\'+\')\n            if parts[0] == \'ctrl\' and parts[1] != \'ctrl\':\n                return f"{parts[1]}+ctrl"\n        return cond\n\n    adata.obs[\'condition\'] = adata.obs[\'condition\'].apply(reformat_condition)\n    new_conditions = adata.obs[\'condition\'].unique()\n    print(f"Reformatted conditions: {len(new_conditions)}")\n\n    # Add required GEARS columns\n    print("Adding GEARS-required columns...")\n    adata.obs[\'cell_type\'] = \'unknown\'  # Required by GEARS\n    adata.obs[\'perturbation\'] = adata.obs[\'condition\']  # Duplicate for compatibility\n    adata.obs[\'control\'] = (adata.obs[\'condition\'] == \'ctrl\').astype(int)\n    adata.obs[\'condition_name\'] = adata.obs[\'condition\']\n    adata.obs[\'organism\'] = \'human\'\n    adata.obs[\'dose_val\'] = 1.0  # Standard dose\n\n    # Compute DE genes using pseudobulk fold-change method\n    print("Computing DE genes (pseudobulk fold-change method)...")\n    adata = compute_de_genes(adata)\n\n    # Compute non-zero gene indices\n    print("Computing non-zero/non-dropout gene indices...")\n    adata = compute_gene_indices(adata)\n\n    # Copy GO graph files from the prepared data directory\n    print("Copying GO graph files...")\n    copy_go_files(inner_dir)\n\n    # Save processed data\n    print(f"Saving processed data to: {output_h5ad}")\n    adata.write_h5ad(output_h5ad)\n\n    print(f"Data preparation complete!")\n    print(f"  - Shape: {adata.shape}")\n    print(f"  - Conditions: {len(adata.obs[\'condition\'].unique())}")\n    print(f"  - Control cells: {adata.obs[\'control\'].sum()}")\n\n    return adata\n\n\ndef compute_de_genes(adata):\n    """\n    Compute differentially expressed genes using pseudobulk fold-change method.\n    This uses the preprocessing fold-change definition required by the GeneCompass workflow.\n    """\n    conditions = adata.obs[\'condition\'].unique()\n    ctrl_mask = adata.obs[\'condition\'] == \'ctrl\'\n\n    # Get dense matrix for computation\n    if issparse(adata.X):\n        X = adata.X.toarray()\n    else:\n        X = adata.X\n\n    # Compute control mean\n    ctrl_mean = X[ctrl_mask].mean(axis=0)\n    ctrl_mean = np.maximum(ctrl_mean, 1e-6)  # Avoid division by zero\n\n    # Compute DE for each perturbation\n    de_genes = {}\n    de_idx = {}\n\n    for cond in conditions:\n        if cond == \'ctrl\':\n            continue\n\n        cond_mask = adata.obs[\'condition\'] == cond\n        if cond_mask.sum() == 0:\n            continue\n\n        # Pseudobulk mean\n        cond_mean = X[cond_mask].mean(axis=0)\n\n        # Log fold change\n        log_fc = np.log2(np.maximum(cond_mean, 1e-6) / ctrl_mean)\n\n        # Get top DE genes by absolute log fold change\n        top_de_idx = np.argsort(np.abs(log_fc))[::-1]\n        de_genes[cond] = log_fc\n        de_idx[cond] = top_de_idx\n\n    # Store in adata.uns\n    adata.uns[\'de_genes\'] = de_genes\n    adata.uns[\'de_idx\'] = de_idx\n    adata.uns[\'top20_DE\'] = {k: v[:20].tolist() for k, v in de_idx.items()}\n    adata.uns[\'top50_DE\'] = {k: v[:50].tolist() for k, v in de_idx.items()}\n\n    print(f"  - Computed DE genes for {len(de_genes)} perturbations")\n\n    return adata\n\n\ndef compute_gene_indices(adata):\n    """\n    Compute non_zeros_gene_idx and non_dropout_gene_idx for each perturbation.\n    """\n    conditions = adata.obs[\'condition\'].unique()\n\n    if issparse(adata.X):\n        X = adata.X.toarray()\n    else:\n        X = adata.X\n\n    non_zeros_gene_idx = {}\n    non_dropout_gene_idx = {}\n    top_non_dropout_de_20 = {}\n    top_non_zero_de_20 = {}\n\n    for cond in conditions:\n        if cond == \'ctrl\':\n            continue\n\n        cond_mask = adata.obs[\'condition\'] == cond\n        if cond_mask.sum() == 0:\n            continue\n\n        cond_data = X[cond_mask]\n\n        # Non-zero: genes expressed in >10% of cells\n        non_zero_frac = (cond_data > 0).mean(axis=0)\n        non_zeros_idx = np.where(non_zero_frac > 0.1)[0]\n        non_zeros_gene_idx[cond] = non_zeros_idx.tolist()\n\n        # Non-dropout: genes with variance (not all same value)\n        gene_var = cond_data.var(axis=0)\n        non_dropout_idx = np.where(gene_var > 0)[0]\n        non_dropout_gene_idx[cond] = non_dropout_idx.tolist()\n\n        # Intersect with DE genes\n        if cond in adata.uns.get(\'de_idx\', {}):\n            de_idx = adata.uns[\'de_idx\'][cond]\n\n            # Top 20 non-dropout DE\n            de_non_dropout = [g for g in de_idx if g in non_dropout_idx]\n            top_non_dropout_de_20[cond] = de_non_dropout[:20]\n\n            # Top 20 non-zero DE\n            de_non_zero = [g for g in de_idx if g in non_zeros_idx]\n            top_non_zero_de_20[cond] = de_non_zero[:20]\n\n    # Store in adata.uns\n    adata.uns[\'non_zeros_gene_idx\'] = non_zeros_gene_idx\n    adata.uns[\'non_dropout_gene_idx\'] = non_dropout_gene_idx\n    adata.uns[\'top_non_dropout_de_20\'] = top_non_dropout_de_20\n    adata.uns[\'top_non_zero_de_20\'] = top_non_zero_de_20\n\n    print(f"  - Computed gene indices for {len(non_zeros_gene_idx)} perturbations")\n\n    return adata\n\n\ndef copy_go_files(output_dir):\n    """Copy GO graph files from the prepared data directory directory."""\n    go_src = GO_FILE\n    go_all_src = GO_ALL_FILE\n\n    go_dst = os.path.join(output_dir, "go.csv")\n    go_all_dst = os.path.join(output_dir, "go_all.pkl")\n\n    if os.path.exists(go_src) and not os.path.exists(go_dst):\n        shutil.copy(go_src, go_dst)\n        print(f"  - Copied go.csv")\n\n    if os.path.exists(go_all_src) and not os.path.exists(go_all_dst):\n        shutil.copy(go_all_src, go_all_dst)\n        print(f"  - Copied go_all.pkl")\n\n\n# =============================================================================\n# STEP 4: Prior knowledge embeddings\n# =============================================================================\n\ndef generate_prior_knowledge_embeddings(adata_path, output_path, embedding_dim=64):\n    """\n    Generate prior knowledge embeddings using PCA from 4 sources:\n    1. Co-expression network\n    2. Gene family\n    3. PECA GRN\n    4. Promoter features\n\n    This matches the exact method used for nocap_prior_knowledge_64.pickle\n    """\n    print_step(4, f"Generating prior knowledge embeddings (dim={embedding_dim})")\n\n    # Load adata to get gene names\n    print(f"Loading gene names from: {adata_path}")\n    adata = sc.read_h5ad(adata_path)\n    gene_names = list(adata.var_names)\n    n_genes = len(gene_names)\n    print(f"Number of genes: {n_genes}")\n\n    # Load prior knowledge sources\n    prior_sources = load_prior_knowledge_sources(gene_names)\n\n    # Concatenate all prior knowledge\n    print("Concatenating prior knowledge sources...")\n    all_features = []\n    for name, features in prior_sources.items():\n        if features is not None:\n            print(f"  - {name}: {features.shape}")\n            all_features.append(features)\n\n    if not all_features:\n        print("WARNING: No prior knowledge sources found. Using random initialization.")\n        embeddings = np.random.randn(n_genes, embedding_dim).astype(np.float32)\n    else:\n        combined = np.concatenate(all_features, axis=1)\n        print(f"Combined features shape: {combined.shape}")\n\n        # Apply PCA to reduce to embedding_dim\n        print(f"Applying PCA to reduce to {embedding_dim} dimensions...")\n        pca = PCA(n_components=embedding_dim)\n        embeddings = pca.fit_transform(combined)\n        print(f"Explained variance ratio: {pca.explained_variance_ratio_.sum():.4f}")\n\n        embeddings = embeddings.astype(np.float32)\n\n    # Create gene to embedding dictionary\n    gene_emb_dict = {gene: embeddings[i] for i, gene in enumerate(gene_names)}\n\n    # Save embeddings\n    os.makedirs(os.path.dirname(output_path), exist_ok=True)\n    with open(output_path, \'wb\') as f:\n        pickle.dump(gene_emb_dict, f)\n\n    print(f"Saved embeddings to: {output_path}")\n    print(f"  - Shape: ({n_genes}, {embedding_dim})")\n\n    return gene_emb_dict\n\n\ndef load_prior_knowledge_sources(gene_names):\n    """\n    Load prior knowledge from multiple sources.\n    Returns a dictionary of feature matrices.\n    """\n    sources = {}\n    n_genes = len(gene_names)\n    gene_to_idx = {g: i for i, g in enumerate(gene_names)}\n\n    # 1. Co-expression network (from simulation split)\n    coexp_path = os.path.join(\n        DATA_DIR, "NOCAP_Telen_512k_normalized",\n        "simulation_1_0.75_0.4_20_co_expression_network.csv"\n    )\n    if os.path.exists(coexp_path):\n        print(f"Loading co-expression network from: {coexp_path}")\n        try:\n            coexp_df = pd.read_csv(coexp_path, index_col=0)\n            coexp_matrix = np.zeros((n_genes, coexp_df.shape[1]))\n            for i, gene in enumerate(gene_names):\n                if gene in coexp_df.index:\n                    coexp_matrix[i] = coexp_df.loc[gene].values\n            sources[\'coexpression\'] = coexp_matrix\n        except Exception as e:\n            print(f"  Warning: Could not load co-expression: {e}")\n\n    # 2. Gene family features (from HGNC or similar)\n    gene_family_path = os.path.join(PRIOR_KNOWLEDGE_DIR, "gene_family.csv")\n    if os.path.exists(gene_family_path):\n        print(f"Loading gene family from: {gene_family_path}")\n        try:\n            family_df = pd.read_csv(gene_family_path, index_col=0)\n            family_matrix = np.zeros((n_genes, family_df.shape[1]))\n            for i, gene in enumerate(gene_names):\n                if gene in family_df.index:\n                    family_matrix[i] = family_df.loc[gene].values\n            sources[\'gene_family\'] = family_matrix\n        except Exception as e:\n            print(f"  Warning: Could not load gene family: {e}")\n\n    # 3. PECA GRN features\n    peca_path = os.path.join(PRIOR_KNOWLEDGE_DIR, "peca_grn.csv")\n    if os.path.exists(peca_path):\n        print(f"Loading PECA GRN from: {peca_path}")\n        try:\n            peca_df = pd.read_csv(peca_path, index_col=0)\n            peca_matrix = np.zeros((n_genes, peca_df.shape[1]))\n            for i, gene in enumerate(gene_names):\n                if gene in peca_df.index:\n                    peca_matrix[i] = peca_df.loc[gene].values\n            sources[\'peca_grn\'] = peca_matrix\n        except Exception as e:\n            print(f"  Warning: Could not load PECA GRN: {e}")\n\n    # 4. Promoter features\n    promoter_path = os.path.join(PRIOR_KNOWLEDGE_DIR, "promoter_features.csv")\n    if os.path.exists(promoter_path):\n        print(f"Loading promoter features from: {promoter_path}")\n        try:\n            promoter_df = pd.read_csv(promoter_path, index_col=0)\n            promoter_matrix = np.zeros((n_genes, promoter_df.shape[1]))\n            for i, gene in enumerate(gene_names):\n                if gene in promoter_df.index:\n                    promoter_matrix[i] = promoter_df.loc[gene].values\n            sources[\'promoter\'] = promoter_matrix\n        except Exception as e:\n            print(f"  Warning: Could not load promoter features: {e}")\n\n    # If no sources found, use existing embeddings as reference\n    if not sources:\n        existing_emb = os.path.join(EMBEDDINGS_DIR, "nocap_prior_knowledge_64.pickle")\n        if os.path.exists(existing_emb):\n            print(f"Loading existing embeddings as reference: {existing_emb}")\n            with open(existing_emb, \'rb\') as f:\n                emb_dict = pickle.load(f)\n            emb_matrix = np.zeros((n_genes, 64))\n            for i, gene in enumerate(gene_names):\n                if gene in emb_dict:\n                    emb_matrix[i] = emb_dict[gene]\n            sources[\'existing\'] = emb_matrix\n\n    return sources\n\n\n# =============================================================================\n# STEP 5: PyG Cell Graphs (from preprocess_pyg_parallel.py)\n# =============================================================================\n\ndef create_pyg_cell_graphs(adata_path, output_dir, n_workers=None):\n    """\n    Create PyTorch Geometric cell graphs for training.\n    Uses parallel processing for efficiency.\n    """\n    print_step(5, "Creating PyG cell graphs")\n\n    # Determine optimal worker count\n    if n_workers is None:\n        available_memory = psutil.virtual_memory().available / (1024**3)  # GB\n        n_workers = max(1, min(mp.cpu_count() - 2, int(available_memory / 8)))\n    print(f"Using {n_workers} workers")\n\n    # Load data\n    print(f"Loading data from: {adata_path}")\n    adata = sc.read_h5ad(adata_path)\n    print(f"Data shape: {adata.shape}")\n\n    # Get expression matrix\n    if issparse(adata.X):\n        X = adata.X.toarray()\n    else:\n        X = adata.X\n\n    # Create output directory\n    pyg_dir = os.path.join(output_dir, "data_pyg")\n    os.makedirs(pyg_dir, exist_ok=True)\n\n    # Process cells in batches\n    n_cells = X.shape[0]\n    batch_size = 10000\n    n_batches = (n_cells + batch_size - 1) // batch_size\n\n    all_graphs = []\n\n    for batch_idx in range(n_batches):\n        start_idx = batch_idx * batch_size\n        end_idx = min(start_idx + batch_size, n_cells)\n\n        print(f"Processing batch {batch_idx + 1}/{n_batches} (cells {start_idx}-{end_idx})")\n\n        batch_X = X[start_idx:end_idx]\n        batch_conditions = adata.obs[\'condition\'].iloc[start_idx:end_idx].values\n\n        # Create graphs for this batch\n        if n_workers > 1:\n            with mp.Pool(n_workers) as pool:\n                batch_graphs = pool.starmap(\n                    create_cell_graph,\n                    [(batch_X[i], batch_conditions[i]) for i in range(len(batch_X))]\n                )\n        else:\n            batch_graphs = [\n                create_cell_graph(batch_X[i], batch_conditions[i])\n                for i in range(len(batch_X))\n            ]\n\n        all_graphs.extend(batch_graphs)\n\n    # Save cell graphs\n    output_path = os.path.join(pyg_dir, "cell_graphs.pkl")\n    print(f"Saving {len(all_graphs)} cell graphs to: {output_path}")\n    with open(output_path, \'wb\') as f:\n        pickle.dump(all_graphs, f)\n\n    print(f"PyG cell graphs complete!")\n\n    return all_graphs\n\n\ndef create_cell_graph(x, condition):\n    """\n    Create a single cell graph as PyG Data object.\n    """\n    x_tensor = torch.tensor(x, dtype=torch.float32).unsqueeze(0)\n    data = Data(x=x_tensor)\n    data.condition = condition\n    return data\n\n\n# =============================================================================\n# Main Pipeline\n# =============================================================================\n\ndef run_full_pipeline():\n    """Run the complete preprocessing pipeline."""\n    print("\\n" + "="*60)\n    print("GeneCompass + GEARS Preprocessing Pipeline")\n    print("="*60)\n    print(f"\\nConfiguration:")\n    print(f"  - Raw data: {RAW_H5AD}")\n    print(f"  - Output dir: {DATA_DIR}")\n    print(f"  - Embeddings dir: {EMBEDDINGS_DIR}")\n    print()\n\n    # Step 1-3: Prepare GEARS data\n    if not os.path.exists(NORMALIZED_H5AD):\n        adata = prepare_gears_data(RAW_H5AD, DATA_DIR)\n    else:\n        print(f"Skipping data preparation (exists): {NORMALIZED_H5AD}")\n        adata = sc.read_h5ad(NORMALIZED_H5AD)\n\n    # Step 4: Generate embeddings\n    emb_path = os.path.join(EMBEDDINGS_DIR, "nocap_prior_knowledge_64.pickle")\n    if not os.path.exists(emb_path):\n        generate_prior_knowledge_embeddings(NORMALIZED_H5AD, emb_path)\n    else:\n        print(f"Skipping embedding generation (exists): {emb_path}")\n\n    # Step 5: Create PyG cell graphs\n    pyg_path = os.path.join(DATA_DIR, "data_pyg", "cell_graphs.pkl")\n    if not os.path.exists(pyg_path):\n        create_pyg_cell_graphs(NORMALIZED_H5AD, DATA_DIR)\n    else:\n        print(f"Skipping PyG generation (exists): {pyg_path}")\n\n    print("\\n" + "="*60)\n    print("Preprocessing complete!")\n    print("="*60)\n\n\ndef main():\n    parser = argparse.ArgumentParser(\n        description="GeneCompass + GEARS Preprocessing Pipeline"\n    )\n    parser.add_argument(\n        "--step",\n        type=str,\n        default="all",\n        choices=["all", "data", "embeddings", "pyg"],\n        help="Which step to run"\n    )\n    parser.add_argument(\n        "--force",\n        action="store_true",\n        help="Force regeneration even if files exist"\n    )\n    parser.add_argument(\n        "--workers",\n        type=int,\n        default=None,\n        help="Number of workers for PyG generation"\n    )\n\n    args = parser.parse_args()\n\n    if args.step == "all":\n        run_full_pipeline()\n    elif args.step == "data":\n        prepare_gears_data(RAW_H5AD, DATA_DIR)\n    elif args.step == "embeddings":\n        emb_path = os.path.join(EMBEDDINGS_DIR, "nocap_prior_knowledge_64.pickle")\n        generate_prior_knowledge_embeddings(NORMALIZED_H5AD, emb_path)\n    elif args.step == "pyg":\n        create_pyg_cell_graphs(NORMALIZED_H5AD, DATA_DIR, n_workers=args.workers)\n\n\nif __name__ == "__main__":\n    main()\n', 'coexpression': '#!/usr/bin/env python\n"""\nPre-compute co-expression network CSV files for specified seeds.\nThis allows parallel training without memory conflicts during network computation.\n"""\n\nimport argparse\nimport sys\nimport os\nimport logging\n\n# Add GEARS to path\nsys.path.insert(0, \'<DATA_ROOT>/05.Behchmarking_DL/GeneCompass/downstream_tasks/gears/gears_code\')\n\nfrom geares import PertData\nfrom geares.utils import get_coexpression_network_from_train\n\nlogging.basicConfig(\n    level=logging.INFO,\n    format=\'%(asctime)s - %(levelname)s - %(message)s\'\n)\nlogger = logging.getLogger(__name__)\n\ndef precompute_network(seed, data_path, data_name):\n    """Pre-compute co-expression network for a specific seed."""\n\n    # Check if CSV already exists\n    csv_path = os.path.join(data_path, data_name,\n                           f\'simulation_{seed}_0.75_0.4_20_co_expression_network.csv\')\n\n    if os.path.exists(csv_path):\n        logger.info(f"Seed {seed}: CSV already exists at {csv_path}")\n        return True\n\n    logger.info(f"Seed {seed}: Loading data...")\n\n    # Load the perturbation data\n    pert_data = PertData(data_path)\n    pert_data.load(data_path=data_path, data_name=data_name)\n\n    logger.info(f"Seed {seed}: Data loaded, shape: {pert_data.adata.shape}")\n\n    # Prepare split (this creates set2conditions)\n    logger.info(f"Seed {seed}: Preparing simulation split...")\n    pert_data.prepare_split(\n        split=\'simulation\',\n        seed=seed,\n        train_gene_set_size=0.75\n    )\n\n    logger.info(f"Seed {seed}: Computing co-expression network...")\n\n    # Compute the co-expression network\n    # Parameters: threshold=0.4, k=20 (matches training)\n    df_co_expression = get_coexpression_network_from_train(\n        adata=pert_data.adata,\n        threshold=0.4,\n        k=20,\n        data_path=data_path,\n        data_name=data_name,\n        split=\'simulation\',\n        seed=seed,\n        train_gene_set_size=0.75,\n        set2conditions=pert_data.set2conditions\n    )\n\n    logger.info(f"Seed {seed}: Network computed! Shape: {df_co_expression.shape}")\n    logger.info(f"Seed {seed}: Saved to {csv_path}")\n\n    return True\n\ndef main():\n    parser = argparse.ArgumentParser(description=\'Pre-compute co-expression networks\')\n    parser.add_argument(\'--seeds\', nargs=\'+\', type=int, required=True,\n                       help=\'Seeds to pre-compute networks for\')\n    parser.add_argument(\'--data_path\', type=str,\n                       default=\'<DATA_ROOT>/05.Behchmarking_DL/data/NOCAP_Telen_512k_normalized\',\n                       help=\'Path to data directory\')\n    parser.add_argument(\'--data_name\', type=str,\n                       default=\'NOCAP_Telen_512k_normalized\',\n                       help=\'Name of the dataset\')\n\n    args = parser.parse_args()\n\n    logger.info(f"Pre-computing co-expression networks for seeds: {args.seeds}")\n    logger.info(f"Data path: {args.data_path}")\n    logger.info(f"Data name: {args.data_name}")\n\n    for seed in args.seeds:\n        try:\n            logger.info(f"\\n{\'=\'*60}")\n            logger.info(f"Processing seed {seed}")\n            logger.info(f"{\'=\'*60}")\n            precompute_network(seed, args.data_path, args.data_name)\n        except Exception as e:\n            logger.error(f"Error processing seed {seed}: {e}")\n            import traceback\n            traceback.print_exc()\n            continue\n\n    logger.info("\\nDone!")\n\nif __name__ == \'__main__\':\n    main()\n', 'train': '#!/usr/bin/env python3\n"""\n01_train_GeneCompass.py - Training script for GeneCompass + GEARS on NOCAP benchmark\n\nFollowing BENCHMARKING_GUIDE.txt requirements:\n- Multiple seed training (5-10 seeds)\n- Simulation split for unseen perturbation prediction\n- 15 epochs with early stopping (patience=5)\n- Saves checkpoints and metrics\n\nUsage:\n    python 01_train_GeneCompass.py --seed 1 --epochs 15\n    python 01_train_GeneCompass.py --seed 1 2 3 4 5 --epochs 15\n"""\n\nimport os\nimport sys\nimport argparse\nimport json\nimport logging\nimport time\nfrom datetime import datetime\nfrom pathlib import Path\n\nimport numpy as np\nimport torch\n\n# Add GEARS code path - use absolute path\nGENECOMPASS_DIR = Path("<DATA_ROOT>/05.Behchmarking_DL/GeneCompass")\nGEARS_CODE_DIR = GENECOMPASS_DIR / "downstream_tasks" / "gears" / "gears_code"\nsys.path.insert(0, str(GEARS_CODE_DIR))\n\nfrom geares import PertData, GEARS\n\n# Setup logging\nlog_dir = GENECOMPASS_DIR / \'codes_GeneCompass\' / \'logs\'\nlog_dir.mkdir(parents=True, exist_ok=True)\n\nlogging.basicConfig(\n    level=logging.INFO,\n    format=\'%(asctime)s - %(levelname)s - %(message)s\',\n    handlers=[\n        logging.StreamHandler(),\n        logging.FileHandler(log_dir / f\'train_{datetime.now().strftime("%Y%m%d_%H%M%S")}.log\')\n    ]\n)\nlogger = logging.getLogger(__name__)\n\n\n# Configuration\nDATA_DIR = Path("<DATA_ROOT>/05.Behchmarking_DL/data")\n# NEW DATA: 512k cells, properly normalized, 61 conditions\nNOCAP_PROCESSED_DIR = DATA_DIR / "NOCAP_Telen_512k_normalized"\nEMBEDDING_FILE = GENECOMPASS_DIR / "embeddings" / "nocap_prior_knowledge_64.pickle"\n# New results directory for 512k data training with EXPANDED pert_emb (18627 genes)\nRESULTS_DIR = GENECOMPASS_DIR / "results" / "NOCAP_512k_benchmark_expanded"\n\n\ndef train_single_seed(seed, epochs=20, batch_size=16, lr=1e-3, device=\'cuda:0\'):\n    """Train a single seed"""\n\n    logger.info(f"\\n{\'=\'*60}")\n    logger.info(f"Training seed {seed}")\n    logger.info(f"{\'=\'*60}")\n\n    # Create results directory\n    seed_dir = RESULTS_DIR / f"seed_{seed}"\n    seed_dir.mkdir(parents=True, exist_ok=True)\n\n    # Check if already fully trained (final model exists)\n    ckpt_file = seed_dir / "ckpt.pth"\n    final_model_file = seed_dir / "model.pt"\n    if final_model_file.exists():\n        logger.info(f"Final model exists for seed {seed}, skipping...")\n        return seed_dir\n    # Note: If only checkpoint_dir exists with partial checkpoints, training will resume\n\n    # Load data\n    logger.info("Loading data...")\n    pert_data = PertData(str(NOCAP_PROCESSED_DIR))\n    pert_data.load(data_path=str(NOCAP_PROCESSED_DIR))\n    logger.info(f"Data loaded: {pert_data.adata.shape}")\n\n    # Prepare split with this seed\n    logger.info(f"Preparing simulation split with seed {seed}...")\n    pert_data.prepare_split(split=\'simulation\', seed=seed)\n    pert_data.get_dataloader(batch_size=batch_size, test_batch_size=batch_size)\n\n    # Log split info\n    train_conds = len(pert_data.set2conditions[\'train\'])\n    val_conds = len(pert_data.set2conditions[\'val\'])\n    test_conds = len(pert_data.set2conditions[\'test\'])\n    logger.info(f"Split: train={train_conds}, val={val_conds}, test={test_conds}")\n\n    # Initialize model\n    logger.info("Initializing model...")\n    gears_model = GEARS(pert_data, device=device)\n    gears_model.model_initialize(\n        damoxing_type=\'prior_knowledge\',\n        hidden_size=64,\n        embedding_file=str(EMBEDDING_FILE)\n    )\n    logger.info(f"Model: num_genes={gears_model.num_genes}, num_perts={gears_model.num_perts}")\n\n    # Train with checkpoint resumability\n    checkpoint_dir = seed_dir / "checkpoints"\n    logger.info(f"Starting training for {epochs} epochs (checkpoint_dir={checkpoint_dir})...")\n    start_time = time.time()\n    gears_model.train(epochs=epochs, lr=lr, checkpoint_dir=str(checkpoint_dir))\n    train_time = time.time() - start_time\n    logger.info(f"Training completed in {train_time:.1f}s")\n\n    # Save model\n    logger.info("Saving model...")\n    gears_model.save_model(str(seed_dir), \'config.pkl\', \'model.pt\')\n\n    # Also save a simple checkpoint\n    torch.save({\n        \'model_state_dict\': gears_model.best_model.state_dict(),\n        \'config\': gears_model.config,\n        \'seed\': seed,\n        \'epochs\': epochs,\n        \'train_time\': train_time\n    }, ckpt_file)\n\n    # Save training info\n    info = {\n        \'seed\': seed,\n        \'epochs\': epochs,\n        \'batch_size\': batch_size,\n        \'lr\': lr,\n        \'train_conditions\': train_conds,\n        \'val_conditions\': val_conds,\n        \'test_conditions\': test_conds,\n        \'num_genes\': gears_model.num_genes,\n        \'num_perts\': gears_model.num_perts,\n        \'train_time\': train_time,\n        \'device\': device\n    }\n    with open(seed_dir / \'training_info.json\', \'w\') as f:\n        json.dump(info, f, indent=2)\n\n    logger.info(f"Seed {seed} training complete!")\n    return seed_dir\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=\'Train GeneCompass + GEARS on NOCAP\')\n    parser.add_argument(\'--seeds\', type=int, nargs=\'+\', default=[1, 2, 3, 4, 5],\n                        help=\'Seeds to train (default: 1 2 3 4 5)\')\n    parser.add_argument(\'--epochs\', type=int, default=15,\n                        help=\'Number of epochs (default: 15, with early stopping patience=5)\')\n    parser.add_argument(\'--batch_size\', type=int, default=16,\n                        help=\'Batch size (default: 16)\')\n    parser.add_argument(\'--lr\', type=float, default=1e-3,\n                        help=\'Learning rate (default: 1e-3)\')\n    parser.add_argument(\'--device\', type=str, default=\'cuda:0\',\n                        help=\'Device (default: cuda:0)\')\n\n    args = parser.parse_args()\n\n    logger.info("GeneCompass + GEARS Training Script")\n    logger.info(f"Seeds: {args.seeds}")\n    logger.info(f"Epochs: {args.epochs}")\n    logger.info(f"Batch size: {args.batch_size}")\n    logger.info(f"Learning rate: {args.lr}")\n    logger.info(f"Device: {args.device}")\n    logger.info(f"Results dir: {RESULTS_DIR}")\n\n    # Create results directory\n    RESULTS_DIR.mkdir(parents=True, exist_ok=True)\n\n    # Train each seed\n    for seed in args.seeds:\n        try:\n            train_single_seed(\n                seed=seed,\n                epochs=args.epochs,\n                batch_size=args.batch_size,\n                lr=args.lr,\n                device=args.device\n            )\n        except Exception as e:\n            logger.error(f"Error training seed {seed}: {e}")\n            import traceback\n            traceback.print_exc()\n            continue\n\n    logger.info("\\n" + "=" * 60)\n    logger.info("All training complete!")\n    logger.info("=" * 60)\n\n\nif __name__ == \'__main__\':\n    main()\n'}


def run_embedded_stage(stage_name, argv):
    source = STAGE_SOURCES[stage_name]
    filename = f"<GeneCompass {stage_name} stage>"
    namespace = {'__name__': '__embedded_stage__', '__file__': filename}
    old_argv = sys.argv[:]
    try:
        sys.argv = [filename] + list(argv)
        exec(compile(source, filename, 'exec'), namespace)
        namespace['main']()
    finally:
        sys.argv = old_argv


def main():
    parser = argparse.ArgumentParser(description='Prepare inputs and train GeneCompass for NOCAP benchmarking')
    parser.add_argument('--skip_preprocess', action='store_true', help='Skip GeneCompass preprocessing')
    parser.add_argument('--skip_coexpression', action='store_true', help='Skip coexpression precomputation')
    parser.add_argument('--skip_train', action='store_true', help='Skip training')
    parser.add_argument('--preprocess_step', default='all', choices=['all', 'data', 'embeddings', 'pyg'], help='Preprocessing step to run')
    parser.add_argument('--force_preprocess', action='store_true', help='Force preprocessing regeneration')
    parser.add_argument('--preprocess_workers', type=int, default=None, help='Workers for PyG preprocessing')
    parser.add_argument('--seeds', type=int, nargs='+', default=[1, 2, 3, 4, 5], help='Seeds for coexpression and training')
    parser.add_argument('--epochs', type=int, default=15, help='Training epochs')
    parser.add_argument('--batch_size', type=int, default=16, help='Training batch size')
    parser.add_argument('--lr', type=float, default=1e-3, help='Training learning rate')
    parser.add_argument('--device', type=str, default='cuda:0', help='Training device')
    parser.add_argument('--coexpression_data_path', default='<DATA_ROOT>/05.Behchmarking_DL/data', help='GEARS data path for coexpression precomputation')
    parser.add_argument('--coexpression_data_name', default='NOCAP_Telen_512k_normalized', help='GEARS data name for coexpression precomputation')
    args = parser.parse_args()

    if not args.skip_preprocess:
        stage_args = ['--step', args.preprocess_step]
        if args.force_preprocess:
            stage_args.append('--force')
        if args.preprocess_workers is not None:
            stage_args += ['--workers', str(args.preprocess_workers)]
        run_embedded_stage('preprocess', stage_args)

    if not args.skip_coexpression:
        stage_args = ['--seeds'] + [str(seed) for seed in args.seeds] + [
            '--data_path', args.coexpression_data_path,
            '--data_name', args.coexpression_data_name,
        ]
        run_embedded_stage('coexpression', stage_args)

    if not args.skip_train:
        stage_args = ['--seeds'] + [str(seed) for seed in args.seeds] + [
            '--epochs', str(args.epochs),
            '--batch_size', str(args.batch_size),
            '--lr', str(args.lr),
            '--device', args.device,
        ]
        run_embedded_stage('train', stage_args)


if __name__ == '__main__':
    main()
